    context=[ex("Un curso quiere investigar una universidad cercana. Proponen dos preguntas: «¿Es grande?» y «¿Qué carreras se estudian y quiénes trabajan allí?». ¿Cuál es mejor? Explica.", "La segunda; se puede responder con información", "Pregunta por servicio y personas.")],
    selfcheck=[ex("¿Qué es una institución pública?", "Una institución del Estado", "No pertenece a particulares."), ex("Escribe un inicio de pregunta de investigación.", "Por ejemplo: ¿Qué...? ¿Quién...? ¿Cómo...? ¿Para qué...?", "Esos inicios abren la investigación."), ex("¿Se puede clasificar una institución por su logo?", "No", "Hay que comprobar su función y a quién pertenece.")],
    open_task=task("Elige una institución de esta lista: Junaeb, Sernac, SII, BancoEstado, Hogar de Cristo o una universidad. Escribe tres preguntas de investigación sobre ella: una sobre el servicio, una sobre los usuarios y otra sobre quiénes trabajan allí.", "Institución: Sernac. ¿Qué servicio presta a las personas? ¿Quiénes usan ese servicio? ¿Qué trabajos hacen las personas que trabajan allí?", ["elige una institución de la lista", "tres preguntas de los tres tipos", "ninguna se contesta con sí o no"], ["tres preguntas escritas"], ["preguntas de sí o no", "preguntas que dependen de opiniones"], "Lee tus preguntas a alguien y comprueba si se podrían responder buscando información."),
    reinforce="Nombra una institución de tu comuna y escribe una pregunta sobre su servicio.",
